begin;
create extension if not exists pgtap with schema extensions;
create temporary table tap_results (result text) on commit drop;
insert into tap_results select plan(5);
insert into auth.users (id,email) values ('11111111-9999-4111-8111-111111111111','authors-host@example.com'),('22222222-9999-4222-8222-222222222222','authors-ada@example.com'),('33333333-9999-4333-8333-333333333333','authors-bea@example.com'),('44444444-9999-4444-8444-444444444444','authors-cid@example.com');
insert into public.content_admin_roles(user_id) values('11111111-9999-4111-8111-111111111111');
insert into public.picture_caption_templates(id,created_by_user_id,name,picture_url,official_caption) values('55555555-9999-4555-8555-555555555555','11111111-9999-4111-8111-111111111111','Authors picture','https://example.com/authors.jpg','Caption this');
select public.create_party('11111111-9999-4111-8111-111111111111','66666666-9999-4666-8666-666666666666',0);
select public.open_party_lobby('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'77777777-9999-4777-8777-777777777777',0);
select public.join_party('22222222-9999-4222-8222-222222222222',(select code from public.parties limit 1),'Ada','88888888-9999-4888-8888-888888888888',1);
select public.join_party('33333333-9999-4333-8333-333333333333',(select code from public.parties limit 1),'Bea','99999999-9999-4999-8999-999999999999',2);
select public.join_party('44444444-9999-4444-8444-444444444444',(select code from public.parties limit 1),'Cid','a0a0a0a0-9999-4a0a-8a0a-a0a0a0a0a0a0',3);
select public.set_party_member_ready('22222222-9999-4222-8222-222222222222',(select id from public.party_members where player_id='22222222-9999-4222-8222-222222222222'),'a1a1a1a1-9999-4a1a-8a1a-a1a1a1a1a1a1',true,4);
select public.set_party_member_ready('33333333-9999-4333-8333-333333333333',(select id from public.party_members where player_id='33333333-9999-4333-8333-333333333333'),'a2a2a2a2-9999-4a2a-8a2a-a2a2a2a2a2a2',true,5);
select public.set_party_member_ready('44444444-9999-4444-8444-444444444444',(select id from public.party_members where player_id='44444444-9999-4444-8444-444444444444'),'a3a3a3a3-9999-4a3a-8a3a-a3a3a3a3a3a3',true,6);
select public.add_picture_caption_round('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'55555555-9999-4555-8555-555555555555','a4a4a4a4-9999-4a4a-8a4a-a4a4a4a4a4a4',7,120,90,120);
select public.start_picture_caption_session('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'a5a5a5a5-9999-4a5a-8a5a-a5a5a5a5a5a5',8);
select public.submit_picture_caption('22222222-9999-4222-8222-222222222222',(select code from public.parties limit 1),'a6a6a6a6-9999-4a6a-8a6a-a6a6a6a6a6a6',9,'Same caption');
select public.submit_picture_caption('33333333-9999-4333-8333-333333333333',(select code from public.parties limit 1),'a7a7a7a7-9999-4a7a-8a7a-a7a7a7a7a7a7',10,'same caption');
insert into tap_results select is((select missing_nicknames from public.host_picture_caption_completion_projection('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1))),array['Cid']::text[],'the Host sees which eligible Player has not submitted a caption yet');
select public.close_picture_captioning('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'a8a8a8a8-9999-4a8a-8a8a-a8a8a8a8a8a8',11,true);
insert into tap_results select is((select count(*) from public.picture_caption_candidate_authors where candidate_id=(select id from public.picture_caption_candidates where not is_official and round_id=(select id from public.picture_caption_rounds where game_session_id=(select current_game_session_id from public.parties limit 1)))),2::bigint,'two identical submissions merge into one candidate with two co-authors');
select public.force_skip_picture_caption_turn('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'a9a9a9a9-9999-4a9a-8a9a-a9a9a9a9a9a9',(select revision from public.game_sessions limit 1));
select public.force_skip_picture_caption_turn('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'b0b0b0b0-9999-4b0b-8b0b-b0b0b0b0b0b0',(select revision from public.game_sessions limit 1));
select public.force_skip_picture_caption_turn('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'b1b1b1b1-9999-4b1b-8b1b-b1b1b1b1b1b1',(select revision from public.game_sessions limit 1));
select public.start_picture_caption_reveal('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'b2b2b2b2-9999-4b2b-8b2b-b2b2b2b2b2b2',(select revision from public.game_sessions limit 1));
insert into tap_results select is((select array_length(author_nicknames,1) from public.host_picture_caption_reveal_projection('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1)) where not is_official),2,'the Host reveal projection lists both co-authors of the merged candidate, unrevealed');
insert into tap_results select is((select author_nicknames from public.picture_caption_results_projection((select id from public.parties limit 1)) where not is_official),null::text[],'the Results projection hides co-author names for a candidate the Host has not revealed yet');
select public.reveal_picture_caption_candidate('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1),'b3b3b3b3-9999-4b3b-8b3b-b3b3b3b3b3b3',(select revision from public.game_sessions limit 1),(select id from public.picture_caption_candidates where not is_official and round_id=(select id from public.picture_caption_rounds where game_session_id=(select current_game_session_id from public.parties limit 1))));
insert into tap_results select is((select count(*) from unnest((select author_nicknames from public.host_picture_caption_reveal_projection('11111111-9999-4111-8111-111111111111',(select id from public.parties limit 1)) where not is_official)) name where name in ('Ada','Bea')),2::bigint,'both co-author names are present once revealed');
insert into tap_results select * from finish();
do $$ declare failures text; begin select string_agg(result,E'\n') into failures from tap_results where result like 'not ok%'; if failures is not null then raise exception using message=failures; end if; end $$;
select result from tap_results;
rollback;
